// A char[N]'s length: the struct's name_len byte when the layout has one (right after kind), else
// up to the first NUL.
function nameLen(dv: DataView, off: number, strOff: number, cap: number): number {
  let n = 0;
  while (n < cap && dv.getUint8(off + strOff + n) !== 0) n++;
  return n;
}

// A list answer: the head, then n records of `size` bytes read by `read`.
export function readList<T>(buf: ArrayBuffer, size: number, read: (dv: DataView, off: number) => T): T[] {
  const dv = new DataView(buf);
  const head = readWList(dv, 0);
  if (head.hash !== WIRE_HASH) throw new Error('wire layout mismatch: rebuild the web (make -C adventurer/server)');
  const out: T[] = [];
  for (let i = 0; i < head.n; i++) out.push(read(dv, SIZE.WList + i * size));
  return out;
}
